import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Prompt Patterns","description":"","frontmatter":{"source":"resources/prompt-patterns.md"},"headers":[],"relativePath":"resources/prompt-patterns.md","filePath":"resources/prompt-patterns.md"}'),o={name:"resources/prompt-patterns.md"};function r(i,e,h,p,l,d){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="prompt-patterns" tabindex="-1">Prompt Patterns <a class="header-anchor" href="#prompt-patterns" aria-label="Permalink to &quot;Prompt Patterns&quot;">​</a></h1><blockquote><p>A library of prompts that work, for any chat assistant or agent. Each pattern says when to use it, gives a prompt you can copy, and names the mistake people usually make with it. Copy them, change the details in <code>[brackets]</code>, and log the ones that worked in your <code>PROMPTS.md</code> (<a href="./../templates/PROMPTS.html">template</a>).</p></blockquote><p>The patterns are not magic words. They work because they make you do the thinking that good results depend on: saying what &quot;done&quot; means, keeping changes small, and checking the AI&#39;s work. One study found that learners who asked the AI for explanations, or asked only conceptual questions and fixed errors themselves, learned far more than learners who handed everything over (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic, 2026</a>).</p><p><strong>On this page:</strong> <a href="#the-three-habits">The three habits</a> · <a href="#quick-index">Quick index</a> · <a href="#the-patterns">The patterns</a> · <a href="#anti-patterns">Anti-patterns</a> · <a href="#where-these-come-from">Where these come from</a></p><hr><h2 id="the-three-habits" tabindex="-1">The three habits <a class="header-anchor" href="#the-three-habits" aria-label="Permalink to &quot;The three habits&quot;">​</a></h2><p>Use these three with any assistant, from week 2 on (that&#39;s when you get the three habits card). They come from what students in a large 2026 beginner course said helped them most (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU 15-113 &quot;Student Wisdom, Fall 2026&quot;</a>), and experienced developers describe the same habits (<a href="https://news.ycombinator.com/item?id=49934037" target="_blank" rel="noreferrer">Hacker News discussion</a>).</p><ol><li><strong>Ask me questions first.</strong> Before the AI builds anything, ask it to ask you clarifying questions, one at a time. Its guesses become your decisions. (<a href="#4-ask-me-questions-first">Pattern 4</a>)</li><li><strong>Show, don&#39;t describe.</strong> Give it a picture or a reference: a photo of your sketch, a screenshot of a page you like, an example of the output you want. It was the most-cited practice on every CMU assignment. (<a href="#13-screenshot-and-wireframe-prompts">Pattern 13</a>)</li><li><strong>Say what works before asking for a change.</strong> List what already works and must keep working, so the AI doesn&#39;t break it while fixing something else. (<a href="#15-say-what-works-first">Pattern 15</a>)</li></ol><hr><h2 id="quick-index" tabindex="-1">Quick index <a class="header-anchor" href="#quick-index" aria-label="Permalink to &quot;Quick index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Pattern</th><th>Use it when</th><th>First used</th></tr></thead><tbody><tr><td>1</td><td><a href="#1-the-four-part-prompt">The four-part prompt</a></td><td>You ask for anything non-trivial</td><td>Week 3</td></tr><tr><td>2</td><td><a href="#2-plan-first">Plan first</a></td><td>A change touches more than one thing</td><td>Week 3</td></tr><tr><td>3</td><td><a href="#3-one-step-at-a-time">One step at a time</a></td><td>You&#39;re working through a plan</td><td>Week 3</td></tr><tr><td>4</td><td><a href="#4-ask-me-questions-first">Ask me questions first</a></td><td>Your idea is still fuzzy</td><td>Week 2</td></tr><tr><td>5</td><td><a href="#5-explain-this-code">Explain this code</a></td><td>You can&#39;t explain a line you&#39;re about to keep</td><td>Week 1</td></tr><tr><td>6</td><td><a href="#6-the-good-bug-report">The good bug report</a></td><td>Something is broken</td><td>Week 3</td></tr><tr><td>7</td><td><a href="#7-review-my-diff">Review my diff</a></td><td>Before you commit a change you didn&#39;t write</td><td>Week 8</td></tr><tr><td>8</td><td><a href="#8-write-a-failing-test-first-redgreen">Write a failing test first</a></td><td>You&#39;re adding a feature or fixing a bug with an agent</td><td>Week 11</td></tr><tr><td>9</td><td><a href="#9-what-could-go-wrong-edge-cases">What could go wrong?</a></td><td>A feature works on the normal case</td><td>Week 5</td></tr><tr><td>10</td><td><a href="#10-compare-two-approaches">Compare two approaches</a></td><td>There&#39;s more than one way to do it</td><td>Week 4</td></tr><tr><td>11</td><td><a href="#11-rubber-duck">Rubber duck</a></td><td>You want to find the bug yourself</td><td>Week 7</td></tr><tr><td>12</td><td><a href="#12-fresh-chat-handoff-summary">Fresh-chat handoff summary</a></td><td>A chat has become long or confused</td><td>Week 3</td></tr><tr><td>13</td><td><a href="#13-screenshot-and-wireframe-prompts">Screenshot and wireframe prompts</a></td><td>Layout matters more than words</td><td>Week 2</td></tr><tr><td>14</td><td><a href="#14-tutor-mode">Tutor mode</a></td><td>You want to learn, not just get an answer</td><td>Week 7</td></tr><tr><td>15</td><td><a href="#15-say-what-works-first">Say what works first</a></td><td>You&#39;re asking for a change to something that mostly works</td><td>Week 2</td></tr><tr><td>16</td><td><a href="#16-check-first-test-prompt">Check-first test prompt</a></td><td>You need a test before the code exists</td><td>Week 6</td></tr><tr><td>17</td><td><a href="#17-teach-back-check">Teach-back check</a></td><td>You&#39;ve written your teach-back and want it checked</td><td>Week 6</td></tr><tr><td>18</td><td><a href="#18-the-goldfish-test">The Goldfish test</a></td><td>You think your SPEC.md or AGENTS.md is finished</td><td>Weeks 5 and 12</td></tr></tbody></table><hr><h2 id="the-patterns" tabindex="-1">The patterns <a class="header-anchor" href="#the-patterns" aria-label="Permalink to &quot;The patterns&quot;">​</a></h2><h3 id="1-the-four-part-prompt" tabindex="-1">1. The four-part prompt <a class="header-anchor" href="#1-the-four-part-prompt" aria-label="Permalink to &quot;1. The four-part prompt&quot;">​</a></h3><p><strong>Use it when:</strong> you ask for anything bigger than a one-line change. This is the Describe step of <a href="./safe-loop.html">the Safe Loop</a>.</p><p><strong>Why it works:</strong> the AI only knows what you tell it. The four parts, <strong>Goal · Context · Constraints · Done when</strong>, cover what it most often has to guess. OpenAI&#39;s guide for its coding agent recommends the same structure for every non-trivial prompt (<a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">Codex best practices</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a dark mode toggle to my home page.</span></span>
<span class="line"><span>Context: My site is a single index.html file with the CSS in a &lt;style&gt; tag and no JavaScript yet. It&#39;s hosted on GitHub Pages.</span></span>
<span class="line"><span>Constraints: Plain HTML, CSS and JavaScript, no libraries. Keep the current colors as the light theme. Don&#39;t change any text or layout.</span></span>
<span class="line"><span>Done when: A button in the top-right corner switches between light and dark; the choice is still there after I reload the page; the button is readable in both modes.</span></span></code></pre></div><p><strong>Common mistake:</strong> a &quot;Done when&quot; you can&#39;t check, such as &quot;looks modern&quot; or &quot;works well&quot;. Write something you could test by using the app: what you click, and what you see.</p><h3 id="2-plan-first" tabindex="-1">2. Plan first <a class="header-anchor" href="#2-plan-first" aria-label="Permalink to &quot;2. Plan first&quot;">​</a></h3><p><strong>Use it when:</strong> the change touches more than one thing, or you&#39;re not sure how it should work. This is the Plan step of the Safe Loop. Agents have a <em>plan mode</em> that does the same.</p><p><strong>Why it works:</strong> fixing a plan takes seconds; fixing code built on a bad plan takes hours. Anthropic&#39;s guide for its coding agent says to plan before implementing, and to skip planning only when you could describe the change in one sentence (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). Observed professionals do the same (<a href="https://arxiv.org/pdf/2512.14012" target="_blank" rel="noreferrer">Huang et al.</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Don&#39;t write any code yet.</span></span>
<span class="line"><span>Propose a plan in 3–6 small steps for the goal above.</span></span>
<span class="line"><span>For each step, say which file changes, what I&#39;ll see when it works, and how I can test it.</span></span>
<span class="line"><span>At the end, list anything you&#39;re unsure about as questions for me.</span></span></code></pre></div><p>Then edit the plan before approving it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Change the plan: drop step 4 (I don&#39;t need animations), and split step 2 into &quot;save&quot; and &quot;load&quot;.</span></span>
<span class="line"><span>Show me the revised plan. Still no code.</span></span></code></pre></div><p><strong>Common mistake:</strong> approving a plan without reading it. Look for steps that change files you didn&#39;t mention, add features you didn&#39;t ask for, or install packages. Ask why, or cut them.</p><h3 id="3-one-step-at-a-time" tabindex="-1">3. One step at a time <a class="header-anchor" href="#3-one-step-at-a-time" aria-label="Permalink to &quot;3. One step at a time&quot;">​</a></h3><p><strong>Use it when:</strong> you have a plan. This is the Step part of the Safe Loop.</p><p><strong>Why it works:</strong> small changes are easy to test, read and undo. In one study, beginners who generated a whole solution from a single prompt got the best first result but did worst when they later had to change the code (<a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">Kazemitabaar et al.</a>). Students who restarted a failing vibe-coded project often chose to go one task at a time (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Do step 2 of the plan only: &quot;Save the list in localStorage&quot;.</span></span>
<span class="line"><span>Show me only the code that changes, and say which file and where it goes.</span></span>
<span class="line"><span>Then stop. Don&#39;t start step 3 until I tell you the tests pass.</span></span></code></pre></div><p><strong>Common mistake:</strong> letting the AI run ahead and do steps 2 to 5 at once, or skipping your own test and commit between steps. If it runs ahead, don&#39;t keep the extra code. Ask again for the one step.</p><h3 id="4-ask-me-questions-first" tabindex="-1">4. Ask me questions first <a class="header-anchor" href="#4-ask-me-questions-first" aria-label="Permalink to &quot;4. Ask me questions first&quot;">​</a></h3><p><strong>Use it when:</strong> your idea is still fuzzy, you&#39;re starting a spec, or you&#39;re about to ask for a first version of anything. This is <a href="#the-three-habits">habit 1</a>.</p><p><strong>Why it works:</strong> the AI fills gaps with guesses. Letting it interview you surfaces those gaps before they become code. Practitioners use exactly this: an LLM asking one question at a time to hone an idea (<a href="https://harper.blog/2025/02/16/my-llm-codegen-workflow-atm/" target="_blank" rel="noreferrer">Harper Reed</a>), or letting the agent interview you before writing a spec (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: I want a small web tool to track which houseplants I&#39;ve watered this week.</span></span>
<span class="line"><span>Before you suggest anything, ask me questions to understand what I need.</span></span>
<span class="line"><span>Ask one question at a time and wait for my answer. Stop after at most 6 questions.</span></span>
<span class="line"><span>Then summarize what you understood in 5 bullet points so I can correct it.</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>🟡 AI limited: in week 5 the AI may interview you and critique your spec, but you write <code>SPEC.md</code> yourself (<a href="./../SYLLABUS.html#8-ai-use-policy">AI use policy</a>).</p></div><p><strong>Common mistake:</strong> answering &quot;whatever you think is best&quot;. Each answer is a decision about <em>your</em> project. If you don&#39;t know, say so, and ask the AI for two options with trade-offs (<a href="#10-compare-two-approaches">pattern 10</a>).</p><h3 id="5-explain-this-code" tabindex="-1">5. Explain this code <a class="header-anchor" href="#5-explain-this-code" aria-label="Permalink to &quot;5. Explain this code&quot;">​</a></h3><p><strong>Use it when:</strong> you&#39;re about to keep code you can&#39;t explain, or you&#39;re preparing for an <a href="./../assessment/oral-walkthroughs.html">oral walkthrough</a>.</p><p><strong>Why it works:</strong> &quot;If you can&#39;t explain it, you didn&#39;t build it.&quot; Asking for explanations alongside code was one of the habits of the learners who scored well in Anthropic&#39;s study (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic, 2026</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain this code to me as if I&#39;m new to programming.</span></span>
<span class="line"><span>First, say what the whole thing does in 2 sentences.</span></span>
<span class="line"><span>Then go line by line: what each line does and why it&#39;s needed, one sentence each.</span></span>
<span class="line"><span>Then name the 3 most important lines, and what would break if I deleted each one.</span></span>
<span class="line"><span>Finally, ask me 2 questions to check I understood. Don&#39;t give the answers until I reply.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste one function, or up to about 30 lines]</span></span></code></pre></div><p><strong>Common mistake:</strong> reading the explanation, nodding, and moving on. Understanding means you can say it without the chat open. Close the chat, explain the code out loud or in writing, then change one thing, predict what will happen, and run it. Explanations can be wrong too; running the code is the real check.</p><h3 id="6-the-good-bug-report" tabindex="-1">6. The good bug report <a class="header-anchor" href="#6-the-good-bug-report" aria-label="Permalink to &quot;6. The good bug report&quot;">​</a></h3><p><strong>Use it when:</strong> something is broken. Use it instead of &quot;fix it&quot;.</p><p><strong>Why it works:</strong> the AI can&#39;t see your screen. Exact error text, what you did, what you expected and what you&#39;ve already tried let it reason about the cause instead of guessing, and stop it from suggesting things you&#39;ve already ruled out.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Fix a bug in my to-do app.</span></span>
<span class="line"><span>What I did: Typed &quot;Buy milk&quot;, pressed Enter, then reloaded the page.</span></span>
<span class="line"><span>What I expected: &quot;Buy milk&quot; is still in the list after reloading.</span></span>
<span class="line"><span>What happened: The list is empty after reload. There are no red errors in the Console.</span></span>
<span class="line"><span>What I tried: In DevTools → Application → Local Storage, the key &quot;todos&quot; exists, but its value is &quot;[object Object]&quot;.</span></span>
<span class="line"><span>Relevant code: the saveTodos function in app.js, pasted below.</span></span>
<span class="line"><span>Constraints: Explain the cause in plain English first, then suggest a fix. Change only this function.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste saveTodos]</span></span></code></pre></div><p><strong>Common mistake:</strong> paraphrasing the error (&quot;it says something about null&quot;). Copy the exact text from the Console or terminal, including the file name and line number. And look before you ask: reading the error yourself is one of the <a href="./without-ai-skills.html#1-read-an-error-message-and-find-the-failing-line">six skills you must show without AI</a>.</p><h3 id="7-review-my-diff" tabindex="-1">7. Review my diff <a class="header-anchor" href="#7-review-my-diff" aria-label="Permalink to &quot;7. Review my diff&quot;">​</a></h3><p><strong>Use it when:</strong> before you commit a change the AI wrote, especially an agent&#39;s. It adds a second pair of eyes to the Read step; it doesn&#39;t replace your own reading.</p><p><strong>Why it works:</strong> AI code is often &quot;almost right&quot;, the top frustration of developers in Stack Overflow&#39;s 2025 survey (<a href="https://survey.stackoverflow.co/2025/ai" target="_blank" rel="noreferrer">Stack Overflow 2025</a>). In the 2026 survey, only 6.6% of developers trusted AI for important decisions, and about 48% trusted it only when they could easily check the answer (<a href="https://stackoverflow.co/company/press/archive/stack-overflow-annual-developer-survey-ai-trust-conditional" target="_blank" rel="noreferrer">Stack Overflow 2026</a>). A reviewer that didn&#39;t write the code is less likely to defend it, so Anthropic&#39;s guide suggests reviewing in a fresh session (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>).</p><p>Get the diff with <code>git diff</code> (before you commit) or <code>git show</code> (your last commit). Then, in a <strong>fresh chat</strong> or a different assistant:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review this diff as a careful senior developer reviewing a junior developer&#39;s code.</span></span>
<span class="line"><span>Context: It should add a delete button to each item. My acceptance criterion is: WHEN I click delete on an item, THE APP SHALL remove it from the list and from localStorage.</span></span>
<span class="line"><span>List, most important first:</span></span>
<span class="line"><span>1. Bugs, or ways it doesn&#39;t meet the criterion</span></span>
<span class="line"><span>2. Security problems (for example innerHTML used with user text, or secrets)</span></span>
<span class="line"><span>3. Changes that weren&#39;t needed for this criterion</span></span>
<span class="line"><span>4. Anything someone new to JavaScript would find hard to explain</span></span>
<span class="line"><span>Don&#39;t rewrite the code. Point to specific lines.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste the diff]</span></span></code></pre></div><p><strong>Common mistake:</strong> asking &quot;Is this OK?&quot; The answer will almost always be yes. Ask for specific kinds of problems. And don&#39;t paste a diff that includes <code>.env</code> or any key.</p><h3 id="8-write-a-failing-test-first-redgreen" tabindex="-1">8. Write a failing test first (red/green) <a class="header-anchor" href="#8-write-a-failing-test-first-redgreen" aria-label="Permalink to &quot;8. Write a failing test first (red/green)&quot;">​</a></h3><p><strong>Use it when:</strong> you&#39;re adding a feature or fixing a bug, especially with an agent (week 11 onward). This is the agent version of <a href="./safe-loop.html#check-first">check first</a>: the test comes before the implementation, in its own prompt. In weeks 6–10, or when you want the test written by something that has never seen the code, use the <a href="#16-check-first-test-prompt">check-first test prompt</a>.</p><p><strong>Why it works:</strong> a test that fails first (red) and then passes (green) proves the test checks something real and that the change fixed it. Simon Willison recommends red/green test-driven development with agents (<a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a>), and Anthropic&#39;s guide says to give the agent a way to verify its own work and to ask for evidence rather than claims (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). An agent has produced false test results before (<a href="https://fortune.com/2025/07/23/ai-coding-tool-replit-wiped-database-called-it-a-catastrophic-failure/" target="_blank" rel="noreferrer">Fortune</a>).</p><p>Red:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a test for acceptance criterion AC2: WHEN I press Add with an empty box, THE APP SHALL add nothing.</span></span>
<span class="line"><span>Context: The list logic is in public/lib/list.js (addItem(list, text) returns a new list). Tests use Node&#39;s built-in runner and live in tests/*.test.js.</span></span>
<span class="line"><span>Constraints: Write the test only. Don&#39;t change any app code. Run npm test and paste the output.</span></span>
<span class="line"><span>Done when: The new test runs and FAILS, and you tell me in one sentence why it fails.</span></span></code></pre></div><p>Green:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Now make the smallest change to public/lib/list.js so that all tests pass.</span></span>
<span class="line"><span>Don&#39;t edit, skip or delete any test. Run npm test and paste the full output.</span></span></code></pre></div><p><strong>Common mistake:</strong> skipping the red step, or letting the agent change the test until it matches buggy code. A test that has never failed might not test anything. Your <a href="./../templates/AGENTS.html">AGENTS.md template</a> says never to disable or delete tests; check the diff to be sure.</p><h3 id="9-what-could-go-wrong-edge-cases" tabindex="-1">9. What could go wrong? (edge cases) <a class="header-anchor" href="#9-what-could-go-wrong-edge-cases" aria-label="Permalink to &quot;9. What could go wrong? (edge cases)&quot;">​</a></h3><p><strong>Use it when:</strong> a feature works on the normal case and you&#39;re about to call it done.</p><p><strong>Why it works:</strong> beginners test the happy path. In one study of students vibe coding, 91.7% of their tests tried common cases, 2.2% tried edge cases, and none wrote a unit test (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>). Edge cases are where &quot;almost right&quot; code breaks.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Here is my acceptance criterion and the code that implements it.</span></span>
<span class="line"><span>List the 8 most likely edge cases a real user could hit (for example empty input, very long text, duplicates, special characters like &lt;b&gt; or emoji, reloading, a small screen, no internet).</span></span>
<span class="line"><span>For each one, say what you think my code does now, and whether that&#39;s a problem.</span></span>
<span class="line"><span>Format them as rows for the manual tests table in my TESTS.md: ID | Checks | Steps | Expected result.</span></span>
<span class="line"><span>Don&#39;t change the code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste criterion and code]</span></span></code></pre></div><p><strong>Common mistake:</strong> trying to handle all of them. Pick the two or three that matter for your users, add them to <a href="./../templates/TESTS.html">TESTS.md template</a>, and put the rest under &quot;Out of scope&quot; in your spec. And don&#39;t trust &quot;what your code does now&quot;: run each test yourself.</p><h3 id="10-compare-two-approaches" tabindex="-1">10. Compare two approaches <a class="header-anchor" href="#10-compare-two-approaches" aria-label="Permalink to &quot;10. Compare two approaches&quot;">​</a></h3><p><strong>Use it when:</strong> there&#39;s more than one reasonable way to build something, or you&#39;re choosing between tools or libraries.</p><p><strong>Why it works:</strong> the first answer an AI gives is one option, not the best one. Asking for two, with trade-offs, puts the decision back with you. In week 4 you&#39;ll also paste the <em>same</em> prompt into two different assistants and compare.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Keep my notes so they&#39;re still there tomorrow.</span></span>
<span class="line"><span>Context: A single-user tool in plain HTML, CSS and JavaScript, hosted on GitHub Pages.</span></span>
<span class="line"><span>Give me two different ways to do this. For each: how it works in 2 sentences, what could go wrong, and how hard it would be for someone new to JavaScript to explain.</span></span>
<span class="line"><span>Recommend one for someone new to JavaScript and say why. Don&#39;t write any code yet.</span></span></code></pre></div><p><strong>Common mistake:</strong> picking the more impressive option that you can&#39;t explain. Choose the one you could defend in an oral walkthrough.</p><h3 id="11-rubber-duck" tabindex="-1">11. Rubber duck <a class="header-anchor" href="#11-rubber-duck" aria-label="Permalink to &quot;11. Rubber duck&quot;">​</a></h3><p><strong>Use it when:</strong> you want to find a bug or understand your code <em>yourself</em>, with the AI only asking questions.</p><p><strong>Why it works:</strong> programmers have long explained their code, line by line, to a rubber duck on the desk; saying it out loud reveals the step where your idea and the code disagree. Here the AI plays the duck, so the thinking stays yours.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m going to explain how my code works, step by step, to find a bug myself.</span></span>
<span class="line"><span>Act as a rubber duck: don&#39;t explain, don&#39;t fix and don&#39;t hint at the answer.</span></span>
<span class="line"><span>After each thing I say, ask me ONE short question that makes me check an assumption, such as &quot;How do you know that variable has a value at that point?&quot;</span></span>
<span class="line"><span>If I ask you for the answer, remind me that I&#39;m the one explaining.</span></span></code></pre></div><p><strong>Common mistake:</strong> the AI slides back into giving answers after a few turns. Paste the rules again, or start fresh. In the Debug Clinic, use only the <a href="#14-tutor-mode">course tutor</a>.</p><h3 id="12-fresh-chat-handoff-summary" tabindex="-1">12. Fresh-chat handoff summary <a class="header-anchor" href="#12-fresh-chat-handoff-summary" aria-label="Permalink to &quot;12. Fresh-chat handoff summary&quot;">​</a></h3><p><strong>Use it when:</strong> a chat has become long, repetitive or confused, or the <a href="./safe-loop.html#the-two-strikes-rule">two-strikes rule</a> says stop.</p><p><strong>Why it works:</strong> a model only sees a limited amount of text at once (its <a href="./glossary.html#context-window">context window</a>), and quality drops as a conversation fills up (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). A fresh chat starts clean. A short summary carries over what matters and leaves the confusion behind.</p><p>In the old chat:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This chat is getting long and we&#39;re going in circles, so I&#39;m starting a fresh chat.</span></span>
<span class="line"><span>Write a handoff summary I can paste into the new chat, under 200 words:</span></span>
<span class="line"><span>- The goal, and the acceptance criterion we&#39;re working on</span></span>
<span class="line"><span>- The files involved and what each one does (one line each)</span></span>
<span class="line"><span>- What works now</span></span>
<span class="line"><span>- What&#39;s broken, with the exact error text</span></span>
<span class="line"><span>- What we tried that did NOT work, and why</span></span>
<span class="line"><span>- Decisions I made that must be kept</span></span>
<span class="line"><span>Don&#39;t include any code, keys or personal data.</span></span></code></pre></div><p>In the new chat, paste the summary, then the <strong>current</strong> version of the file that matters, then a four-part prompt for the next step.</p><p><strong>Common mistake:</strong> carrying the old chat&#39;s wrong theory into the new one. Read the summary before pasting it. Delete any guess that&#39;s written as if it were a fact (&quot;the problem is the CSS&quot;) unless you&#39;ve confirmed it.</p><h3 id="13-screenshot-and-wireframe-prompts" tabindex="-1">13. Screenshot and wireframe prompts <a class="header-anchor" href="#13-screenshot-and-wireframe-prompts" aria-label="Permalink to &quot;13. Screenshot and wireframe prompts&quot;">​</a></h3><p><strong>Use it when:</strong> layout matters more than words: building a screen from your <a href="./glossary.html#wireframe">wireframe</a>, matching a style you like, or showing a visual bug. Most chat assistants accept images; check that yours does. This is <a href="#the-three-habits">habit 2</a>: show, don&#39;t describe.</p><p><strong>From a wireframe:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Build the layout of my main screen from the attached photo of my wireframe.</span></span>
<span class="line"><span>Context: This is the wireframe from my SPEC.md. The labels on the sketch are the real button texts.</span></span>
<span class="line"><span>Constraints: HTML and CSS only, no JavaScript yet. Use simple class names I can read. It must work on a phone screen.</span></span>
<span class="line"><span>Done when: Every box on the sketch is on the page in the same arrangement, and nothing extra has been added.</span></span></code></pre></div><p><strong>From a reference</strong> (a screenshot of a page whose look you like):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Restyle my home page using the attached screenshot as a reference for layout and spacing.</span></span>
<span class="line"><span>Context: My page is a single index.html with the CSS in a &lt;style&gt; tag. The screenshot is someone else&#39;s site.</span></span>
<span class="line"><span>Constraints: Borrow the layout ideas only: a wide header, a two-column projects grid, lots of white space. Don&#39;t copy their text, images, logo or colors. Keep my content.</span></span>
<span class="line"><span>Done when: My page has the same overall arrangement as the reference, with my own words and colors, and still works at phone width.</span></span></code></pre></div><p><strong>For a visual bug:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The attached screenshot shows my page at phone size (DevTools device toolbar).</span></span>
<span class="line"><span>Expected: the Add button sits to the right of the input box.</span></span>
<span class="line"><span>What happens: the button drops below the box and sticks out past the right edge of the screen.</span></span>
<span class="line"><span>Here is the CSS for that section: [paste]</span></span>
<span class="line"><span>Explain the cause first, then suggest the smallest fix.</span></span></code></pre></div><p><strong>Common mistake:</strong> a screenshot of an error message. Copy error <em>text</em> instead; the AI can misread images, and you can&#39;t search a picture. And crop every screenshot first. Anything visible, such as your email, other tabs or a key, is being sent to the AI company (<a href="./../setup/safety-contract.html">safety contract rule 2</a>).</p><h3 id="14-tutor-mode" tabindex="-1">14. Tutor mode <a class="header-anchor" href="#14-tutor-mode" aria-label="Permalink to &quot;14. Tutor mode&quot;">​</a></h3><p><strong>Use it when:</strong> you want to learn something, not just get it done. For example, you&#39;re stuck on a Debug Clinic bug after ten minutes of trying (🟡 AI limited: tutor mode is the only AI allowed there), or practicing for an oral walkthrough.</p><p><strong>Why it works:</strong> in a large trial, students with an unrestricted chatbot did better in practice but worse on the exam, without noticing. A tutor that only gave hints avoided that harm (<a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al., PNAS</a>). Harvard&#39;s CS50 uses a hint-giving tutor for the same reason (<a href="https://cs.harvard.edu/malan/publications/V1fp0567-liu.pdf" target="_blank" rel="noreferrer">Liu et al.</a>).</p><p><strong>How:</strong> open a new chat and paste the course tutor prompt from <a href="./tutor-mode.html#the-tutor-prompt">Tutor mode</a>. Then describe your problem:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m working on bug 2 in the Debug Clinic. When I click &quot;Add&quot;, nothing happens.</span></span>
<span class="line"><span>The Console shows: Uncaught TypeError: Cannot read properties of null (reading &#39;value&#39;) at app.js:14</span></span>
<span class="line"><span>I think the input box isn&#39;t being found, but I don&#39;t know why.</span></span>
<span class="line"><span>Give me a hint, not the answer.</span></span></code></pre></div><p><strong>Common mistake:</strong> &quot;just tell me the answer&quot;, or quietly switching to a normal chat. That turns the tutor back into the thing the research warns about. If a hint doesn&#39;t help, ask for a smaller one, or ask the instructor.</p><h3 id="15-say-what-works-first" tabindex="-1">15. Say what works first <a class="header-anchor" href="#15-say-what-works-first" aria-label="Permalink to &quot;15. Say what works first&quot;">​</a></h3><p><strong>Use it when:</strong> you&#39;re asking for a change to something that mostly works: a new feature, a style change, or a fix for one bug. This is <a href="#the-three-habits">habit 3</a>.</p><p><strong>Why it works:</strong> when an AI changes code, it can quietly rewrite parts you didn&#39;t mention. Telling it what already works tells it what to protect, and gives you a list to re-test afterwards. Students in a 2026 beginner course named this as one of their most useful practices (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What works now and must keep working: adding an item, the delete button on each item, and the list surviving a reload.</span></span>
<span class="line"><span>Change I want: a &quot;clear all&quot; button above the list that asks me to confirm first.</span></span>
<span class="line"><span>Constraints: Don&#39;t change how adding or deleting works. Change as few lines as you can.</span></span>
<span class="line"><span>Before you write any code, tell me which of the working features your change could affect, and how.</span></span></code></pre></div><p><strong>Common mistake:</strong> listing what works but not checking it afterwards. After the change, test every item on your &quot;works now&quot; list again, not only the new feature. If one broke, that&#39;s a bug report (<a href="#6-the-good-bug-report">pattern 6</a>), not a reason to start over.</p><h3 id="16-check-first-test-prompt" tabindex="-1">16. Check-first test prompt <a class="header-anchor" href="#16-check-first-test-prompt" aria-label="Permalink to &quot;16. Check-first test prompt&quot;">​</a></h3><p><strong>Use it when:</strong> you&#39;re about to ask for a feature or a fix and need its check first, from week 6 onward (or in week 4, for your first automated test). This is the <a href="./safe-loop.html#check-first">check first</a> habit of the Safe Loop.</p><p><strong>Why it works:</strong> tests written by an AI that has already seen faulty code tend to agree with the faults. In one 2026 study, tests written after buggy code caught 14% of the faults, against 25% for tests written independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). So the test-writer gets the criterion and the function&#39;s name, <strong>not</strong> the code. Use a <strong>separate prompt</strong>: a fresh chat, or a new Copilot Chat session, before you ask for the implementation.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Write ONE automated test for this acceptance criterion, before the code exists.</span></span>
<span class="line"><span>Criterion: WHEN I add an item whose text is only spaces, THE APP SHALL leave the list unchanged.</span></span>
<span class="line"><span>Context: The function will be addItem(list, text) in public/lib/list.js. It takes an array of strings and returns a new array. Tests use Node&#39;s built-in runner (node --test) and live in tests/list.test.js.</span></span>
<span class="line"><span>Constraints: You haven&#39;t seen the code and shouldn&#39;t ask for it. Test only this criterion. Use plain assert, no libraries. Add a one-line comment saying what the test checks.</span></span>
<span class="line"><span>Done when: The test file runs with node --test, and it would fail if addItem added the item.</span></span></code></pre></div><p>Then run the test <strong>before</strong> you ask for the code. It should fail (red), or report that <code>addItem</code> doesn&#39;t exist yet. Only then write the implementation prompt (<a href="#8-write-a-failing-test-first-redgreen">pattern 8</a> shows the agent version).</p><p><strong>Common mistake:</strong> pasting the test prompt into the same chat that will write (or already wrote) the code. The point is that the test doesn&#39;t know the code. Second mistake: accepting a test you can&#39;t read. Before you keep it, say in one sentence what input it uses and what result it expects.</p><h3 id="17-teach-back-check" tabindex="-1">17. Teach-back check <a class="header-anchor" href="#17-teach-back-check" aria-label="Permalink to &quot;17. Teach-back check&quot;">​</a></h3><p><strong>Use it when:</strong> you&#39;ve written your <a href="./safe-loop.html#teach-back">teach-back</a> for a change and want to know whether it matches what the code actually does. Write the teach-back <strong>first</strong>, yourself; this prompt only checks it.</p><p><strong>Why it works:</strong> explaining code in your own words before you accept it is what protected learners when the AI was taken away: 39% failed a no-AI maintenance task with an explanation step, against 77% without one (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>). A check against the diff catches the parts you explained wrongly or skipped.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m about to commit the change in this diff. Below the diff is my own explanation of it.</span></span>
<span class="line"><span>Check my explanation against the diff. Don&#39;t rewrite my explanation and don&#39;t change the code.</span></span>
<span class="line"><span>Tell me:</span></span>
<span class="line"><span>1. Anything I said that the diff doesn&#39;t actually do</span></span>
<span class="line"><span>2. Any change in the diff that I didn&#39;t mention</span></span>
<span class="line"><span>3. One question an examiner could ask me about this change that my explanation doesn&#39;t answer</span></span>
<span class="line"><span>Then stop. I&#39;ll fix my explanation myself.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Diff:</span></span>
<span class="line"><span>[paste the output of git diff]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>My explanation:</span></span>
<span class="line"><span>[paste your 2–3 sentences]</span></span></code></pre></div><p><strong>Common mistake:</strong> asking the AI to &quot;improve&quot; your teach-back and pasting its version into <code>PROMPTS.md</code>. The teach-back is graded because it&#39;s yours. Fix your own sentences, and if point 3 stumps you, find the answer in the code before you commit.</p><h3 id="18-the-goldfish-test" tabindex="-1">18. The Goldfish test <a class="header-anchor" href="#18-the-goldfish-test" aria-label="Permalink to &quot;18. The Goldfish test&quot;">​</a></h3><p><strong>Use it when:</strong> you think your <code>SPEC.md</code> is finished: Project 1&#39;s in week 5, and the capstone&#39;s (with its <code>AGENTS.md</code>) in week 12.</p><p><strong>Why it works:</strong> a goldfish, the story goes, forgets everything in seconds. A fresh chat is the same: it knows nothing about your project except what you paste. If it can&#39;t understand and build from your document alone, the document is leaning on things that live only in your head or in an old chat. The test comes from a 2026 University of Michigan course (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">EGM README</a>), and writing skill turns out to predict how well students vibe code (<a href="https://arxiv.org/abs/2603.14133" target="_blank" rel="noreferrer">Thorgeirsson et al.</a>).</p><p><strong>How:</strong> open a <strong>fresh chat</strong> (a temporary chat if your assistant remembers past conversations). Paste <strong>only</strong> the document, then:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The document above is everything you know about this project. Don&#39;t build anything yet.</span></span>
<span class="line"><span>1. In 5 bullets, say what you would build from it.</span></span>
<span class="line"><span>2. List every question you&#39;d need answered before you could build it without guessing.</span></span>
<span class="line"><span>3. Point out anything vague, missing or contradictory, quoting the line.</span></span>
<span class="line"><span>4. Name the 3 things you would most likely get wrong if you started now.</span></span></code></pre></div><p>Write down what it asked or got wrong (in <code>PROMPTS.md</code>, or the place your lab says), then revise the document so a fresh chat wouldn&#39;t need to ask. Run the test again on the revised version if you have time.</p><p><strong>Common mistake:</strong> answering the chat&#39;s questions in the chat. That fixes the chat, not the document. Every answer belongs in <code>SPEC.md</code> or <code>AGENTS.md</code>. For <code>AGENTS.md</code>, add one more question: &quot;Which folders may you change, and what must you ask me before doing?&quot; If it can&#39;t answer from the Scope section, revise Scope.</p><hr><h2 id="anti-patterns" tabindex="-1">Anti-patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-patterns&quot;">​</a></h2><p>These feel natural and waste time, credits, or both.</p><h3 id="vague-prompts" tabindex="-1">Vague prompts <a class="header-anchor" href="#vague-prompts" aria-label="Permalink to &quot;Vague prompts&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Make my website better.</span></span></code></pre></div><p>The AI has to guess what &quot;better&quot; means, so it guesses big: new colors, new sections, rewritten text, and a diff you can&#39;t review. <strong>Instead:</strong> use <a href="#1-the-four-part-prompt">the four-part prompt</a> with one goal and a &quot;Done when&quot; you can check.</p><h3 id="mega-prompts" tabindex="-1">Mega-prompts <a class="header-anchor" href="#mega-prompts" aria-label="Permalink to &quot;Mega-prompts&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build me a full app with login, a database, payments, a chat, dark mode, an admin panel and an AI assistant.</span></span></code></pre></div><p>You&#39;ll get a lot of code at once that you can&#39;t test, can&#39;t explain and can&#39;t change later. Whole-solution prompts give the best first try and the worst later changes (<a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">Kazemitabaar et al.</a>), and they burn through free credits. This is how people hit the &quot;70% wall&quot;: most of the way there fast, then every fix breaks something else (<a href="https://addyo.substack.com/p/the-70-problem-hard-truths-about" target="_blank" rel="noreferrer">Osmani</a>). <strong>Instead:</strong> write a <a href="./../templates/SPEC.html">spec</a>, then <a href="#2-plan-first">plan first</a>, then go <a href="#3-one-step-at-a-time">one step at a time</a>.</p><h3 id="fix-it" tabindex="-1">&quot;Fix it&quot; <a class="header-anchor" href="#fix-it" aria-label="Permalink to &quot;&quot;Fix it&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>It doesn&#39;t work. Fix it.</span></span></code></pre></div><p>The AI will change <em>something</em>, often not the right thing, and you learn nothing. In one study, 61% of students&#39; prompts were debugging requests like this (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>). Non-programmers tend to re-prompt instead of debugging (<a href="https://arxiv.org/html/2605.24521v1" target="_blank" rel="noreferrer">Fawzy et al.</a>), and learners who used AI to debug instead of to understand scored lowest (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic</a>). <strong>Instead:</strong> read the error yourself, then write <a href="#6-the-good-bug-report">a good bug report</a>.</p><h3 id="pasting-secrets" tabindex="-1">Pasting secrets <a class="header-anchor" href="#pasting-secrets" aria-label="Permalink to &quot;Pasting secrets&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Here&#39;s my .env file, why doesn&#39;t my key work?</span></span>
<span class="line"><span>LLM_API_KEY=...</span></span></code></pre></div><p>Anything you paste can be stored, read by reviewers and used for training (<a href="./../setup/safety-contract.html">safety contract rule 2</a>). <strong>Instead:</strong> describe it without the value: &quot;My <code>.env</code> has <code>LLM_API_KEY</code> set, with no quotes or spaces, and I restarted the server after editing it.&quot; Replace real values with placeholders such as <code>[MY_KEY]</code>. If you&#39;ve already pasted a key: <a href="./troubleshooting.html#i-committed-a-secret">revoke it now</a>.</p><h3 id="arguing-with-a-confused-chat" tabindex="-1">Arguing with a confused chat <a class="header-anchor" href="#arguing-with-a-confused-chat" aria-label="Permalink to &quot;Arguing with a confused chat&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NO. For the third time, do NOT change the header!!</span></span></code></pre></div><p>Once a conversation has gone wrong, the mistakes stay in its context and keep pulling it back. More capital letters won&#39;t help. Anthropic&#39;s guide says that after two failed corrections, you should clear the conversation and write a better prompt (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). <strong>Instead:</strong> follow <a href="./safe-loop.html#the-two-strikes-rule">the two-strikes rule</a>: go back to your last good commit if things got worse, write a <a href="#12-fresh-chat-handoff-summary">handoff summary</a>, and start a fresh chat with a sharper prompt.</p><hr><h2 id="where-these-come-from" tabindex="-1">Where these come from <a class="header-anchor" href="#where-these-come-from" aria-label="Permalink to &quot;Where these come from&quot;">​</a></h2><p>These patterns combine vendor guides, practitioners and education research. The evidence behind them is mostly practitioner experience, not controlled trials; see <a href="./../research/design-rationale.html">Why the Course Looks Like This</a> for how the course uses it.</p><ul><li>Goal · Context · Constraints · Done when: <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">OpenAI Codex best practices</a></li><li>Plan first, verify with evidence, fresh sessions, two failed corrections: <a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a></li><li>Red/green testing: <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Willison, Agentic Engineering Patterns</a></li><li>Interview-style spec building: <a href="https://harper.blog/2025/02/16/my-llm-codegen-workflow-atm/" target="_blank" rel="noreferrer">Harper Reed</a></li><li>The three habits (ask questions first, show a reference, say what works): <a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU 15-113 Fall 2026 report</a></li><li>Writing the test independently of the code: <a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a></li><li>Explaining before accepting (teach-back): <a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a></li><li>The Goldfish test: <a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">Michigan EECS 498 EGM</a></li><li>Learning-friendly habits (ask for explanations, fix errors yourself): <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic, 2026</a></li><li>Hint-only tutors: <a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al., PNAS</a></li><li>What novices actually do when vibe coding: <a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a></li></ul><p>More reading: <a href="./reading-list.html">Reading List</a>.</p>`,143)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
